  @Override
  public void close() {
    if (ownedChannel == null) {
      return;
    }
    ownedChannel.shutdown();
    try {
      if (!ownedChannel.awaitTermination(5, TimeUnit.SECONDS)) {
        ownedChannel.shutdownNow();
      }
    } catch (InterruptedException err) {
      ownedChannel.shutdownNow();
      Thread.currentThread().interrupt();
    }
  }

  // ── Neutral-IR typed query builder (master-plan items 2.5 / 10.1) ─────────────
  //
  // A thin, typed layer that emits the broker's CANONICAL neutral-IR envelope
  // ({"ir": {"op": ..., ...LogicalRead/Write/Delete}}) and sends it through the
  // EXISTING GenericDispatch RPC — this client's own generated GenericDispatch
  // unary forwarder (with its retry / deadline / metadata / error mapping). It is
  // NOT a second client engine: it builds a GenericDispatchRequest and hands it to
  // the very same dispatch method raw callers use, so tenant / project / auth all
  // flow from the caller's RequestContext metadata exactly as they do for a raw
  // call. The builder NEVER puts a tenant/project (or any RequestContext) on the
  // request body — the broker derives those from the verified claim / headers.
  //
  // The broker parses this envelope in handlers_data.rs::compile_neutral_ir_dispatch
  // and lowers it to backend-native SQL/query with tenant + RLS predicates injected
  // server-side, so the safe, mediated path is the one users naturally take. Raw
  // spec stays available as an explicit escape hatch — see rawDispatchRequest below
  // and the untouched GenericDispatch(...) wrapper.
  //
  // The wire shapes mirror the serde encoding of the Rust IR types (src/ir/*.rs):
  // externally-tagged enums ({"Comparison": {...}}, {"String": "x"}, the unit
  // "Null"), snake_case op tokens ("eq", "like"), and the
  // LogicalRead/LogicalWrite/LogicalDelete field names. The serialized envelope is
  // byte-identical to the TypeScript / Python SDKs' for the same logical query:
  // compact JSON, fixed key order (the writers below emit keys in the same order),
  // sorted record keys (a TreeMap mirrors the server-side BTreeMap canonicalization
  // and the other SDKs' explicit sort), JSON.stringify-compatible string escaping,
  // and no HTML escaping.

  /** Backend whose neutral-IR compiler lowers the envelope when the caller does
   *  not pick one explicitly. The broker resolves the concrete instance per project. */
  public static final String DEFAULT_IR_BACKEND = "postgres";

  public static final Map<String, String> ORM_TIERS = Map.ofEntries(Map.entry("postgres", "relational"), Map.entry("mysql", "relational"), Map.entry("sqlite", "relational"), Map.entry("sqlserver", "relational"), Map.entry("clickhouse", "relational"), Map.entry("redis", "kv"), Map.entry("memcached", "kv"), Map.entry("qdrant", "vector"), Map.entry("weaviate", "vector"), Map.entry("pinecone", "vector"), Map.entry("minio", "blob"), Map.entry("s3", "blob"), Map.entry("azureblob", "blob"), Map.entry("gcs", "blob"), Map.entry("mongodb", "document"), Map.entry("elasticsearch", "vector"), Map.entry("neo4j", "graph"), Map.entry("cassandra", "relational"));

