      Ir.string(sb, messageType);
      String filter = filterFragment();
      if (filter != null) {
        sb.append(",\"filter\":").append(filter);
      }
      if (projection != null && !projection.isEmpty()) {
        sb.append(",\"projection\":{\"fields\":");
        Ir.stringArray(sb, projection);
        sb.append('}');
      }
      if (!sorts.isEmpty()) {
        sb.append(",\"sort\":[");
        for (int i = 0; i < sorts.size(); i++) {
          if (i > 0) {
            sb.append(',');
          }
          sb.append("{\"field\":");
          Ir.string(sb, sorts.get(i)[0]);
          sb.append(",\"direction\":");
          Ir.string(sb, sorts.get(i)[1]);
          sb.append('}');
        }
        sb.append(']');
      }
      if (!includes.isEmpty()) {
        sb.append(",\"include\":[");
        for (int i = 0; i < includes.size(); i++) {
          if (i > 0) {
            sb.append(',');
          }
          sb.append("{\"relation\":");
          Ir.string(sb, includes.get(i));
          sb.append('}');
        }
        sb.append(']');
      }
      if (limit != null || offset != null) {
        sb.append(",\"pagination\":{");
        boolean wrote = false;
        if (limit != null) {
          sb.append("\"limit\":").append(limit.intValue());
          wrote = true;
        }
        if (offset != null) {
          if (wrote) {
            sb.append(',');
          }
          sb.append("\"offset\":").append(offset.intValue());
        }
        sb.append('}');
      }
      sb.append("}}");
      return sb.toString();
