  /**
   * Typed neutral-IR write builder. Emits {@code {"ir": {"op": "write", ...}}} (a
   * {@code LogicalWrite}). Defaults to insert (conflict = {@code Error}); call
   * {@code merge()} / {@code ignoreConflicts()} / {@code updateOnConflict(...)} for
   * upsert semantics.
   */
  public static final class WriteQuery {
    private final String messageType;
    private final List<Map<String, Object>> rows = new ArrayList<>();
    private String conflict;
    private final List<String> returnFields = new ArrayList<>();

    WriteQuery(String messageType) {
      this.messageType = messageType;
    }

    public WriteQuery record(Map<String, Object> row) {
      rows.add(row);
      return this;
    }

    public WriteQuery records(Iterable<? extends Map<String, Object>> rows) {
      for (Map<String, Object> row : rows) {
        this.rows.add(row);
      }
      return this;
    }

    /** Full upsert — replace every column on conflict ({@code ConflictStrategy::Replace}). */
    public WriteQuery merge() {
      this.conflict = "{\"kind\":\"replace\"}";
      return this;
    }

    /** Skip conflicting rows ({@code ConflictStrategy::Ignore}). */
    public WriteQuery ignoreConflicts() {
      this.conflict = "{\"kind\":\"ignore\"}";
      return this;
    }

    /** Partial upsert — update only {@code fields} on conflict
     *  ({@code ConflictStrategy::Update}). {@code conflictOn} names an alternate
     *  unique key; pass null/empty to use the manifest PK. */
    public WriteQuery updateOnConflict(List<String> fields, List<String> conflictOn) {
      StringBuilder c = new StringBuilder("{\"kind\":\"update\",\"fields\":");
      Ir.stringArray(c, fields);
      if (conflictOn != null && !conflictOn.isEmpty()) {
        c.append(",\"conflict_on\":");
        Ir.stringArray(c, conflictOn);
      }
      c.append('}');
      this.conflict = c.toString();
      return this;
    }

    public WriteQuery returning(String... fields) {
      for (String f : fields) {
        returnFields.add(f);
      }
      return this;
    }

    public String toSpecJson() {
      if (rows.isEmpty()) {
        throw new IllegalStateException("udb: write requires at least one record(...)");
      }
      StringBuilder sb = new StringBuilder("{\"ir\":{\"op\":\"write\",\"message_type\":");
      Ir.string(sb, messageType);
      sb.append(",\"records\":[");
      for (int i = 0; i < rows.size(); i++) {
        if (i > 0) {
          sb.append(',');
        }
        writeRecord(sb, rows.get(i));
      }
      sb.append(']');
      if (conflict != null) {
        sb.append(",\"conflict\":").append(conflict);
      }
      if (!returnFields.isEmpty()) {
        sb.append(",\"return_fields\":");
        Ir.stringArray(sb, returnFields);
      }
      sb.append("}}");
      return sb.toString();
    }

    /** One {@code LogicalRecord} with keys sorted for cross-language byte-stability. */
    private static void writeRecord(StringBuilder sb, Map<String, Object> row) {
      Map<String, Object> sorted = new TreeMap<>(row);
      sb.append('{');
      boolean first = true;
      for (Map.Entry<String, Object> e : sorted.entrySet()) {
        if (!first) {
          sb.append(',');
        }
        first = false;
        Ir.string(sb, e.getKey());
        sb.append(':');
        Ir.writeLogicalValue(sb, e.getValue());
      }
      sb.append('}');
    }

    public com.udb.entity.v1.GenericDispatchRequest toRequest() {
      return toRequest(DEFAULT_IR_BACKEND);
    }

    public com.udb.entity.v1.GenericDispatchRequest toRequest(String backend) {
      return Ir.dispatchRequest(backend, "mutate", toSpecJson());
    }

    public com.udb.entity.v1.GenericDispatchResponse execute(GeneratedUdbClient client) {
      return execute(client, DEFAULT_IR_BACKEND);
    }

    public com.udb.entity.v1.GenericDispatchResponse execute(GeneratedUdbClient client, String backend) {
      return client.GenericDispatch(toRequest(backend));
    }
  }

