  public static final class Repository {
    private final EntityBinding binding;

    Repository(EntityBinding binding) {
      this.binding = binding;
      if (binding.primaryKeys().isEmpty()) {
        throw new IllegalArgumentException(
            "udb: entity " + binding.messageType() + " has no descriptor primary key");
      }
    }

    public EntityBinding binding() {
      return binding;
    }

    public Query query() {
      return GeneratedUdbClient.query(binding.messageType());
    }

    public List<EntityRelationBinding> relations() {
      return binding.relations();
    }

    public EntityRelationBinding relation(String name) {
      for (EntityRelationBinding relation : binding.relations()) {
        if (relation.name().equals(name)) {
          return relation;
        }
      }
      return null;
    }

    public EntityRelationBinding requireRelation(String name) {
      EntityRelationBinding relation = relation(name);
      if (relation == null) {
        throw new IllegalArgumentException(
            "udb: unknown relation " + name + " on entity " + binding.messageType());
      }
      if (relation.localFields().isEmpty()
          || relation.localFields().size() != relation.targetFields().size()) {
        throw new IllegalStateException(
            "udb: relation " + name + " on entity " + binding.messageType() + " has invalid field mapping");
      }
      if (relation.targetMessageType().isBlank()) {
        throw new IllegalStateException(
            "udb: relation " + name + " on entity " + binding.messageType() + " has no target entity");
      }
      return relation;
    }

    public Query relationQuery(String name, Map<String, Object> parent) {
      EntityRelationBinding relation = requireRelation(name);
      Query q = GeneratedUdbClient.query(relation.targetMessageType());
      for (int idx = 0; idx < relation.localFields().size(); idx++) {
        String localField = relation.localFields().get(idx);
        if (!parent.containsKey(localField)) {
          throw new IllegalArgumentException(
              "udb: relation " + name + " missing parent field " + localField);
        }
        q.where(relation.targetFields().get(idx), "eq", parent.get(localField));
      }
      return q;
    }

    public Query relationBatchQuery(String name, List<Map<String, Object>> parents) {
      EntityRelationBinding relation = requireRelation(name);
      if (relation.localFields().size() != relation.targetFields().size()) {
        throw new IllegalStateException(
            "udb: relation " + name + " on entity " + binding.messageType() + " has invalid field mapping");
      }
      if (parents.isEmpty()) {
        throw new IllegalArgumentException(
            "udb: relation " + name + " batch query requires at least one parent");
      }
      if (relation.localFields().size() == 1) {
        String localField = relation.localFields().get(0);
        List<Object> values = new ArrayList<>();
        List<String> seen = new ArrayList<>();
        for (Map<String, Object> parent : parents) {
          if (!parent.containsKey(localField)) {
            throw new IllegalArgumentException(
                "udb: relation " + name + " missing parent field " + localField);
          }
          Object value = parent.get(localField);
          String key = value == null ? "null" : value.getClass().getName() + ":" + String.valueOf(value);
          if (!seen.contains(key)) {
            seen.add(key);
            values.add(value);
          }
        }
        return GeneratedUdbClient.query(relation.targetMessageType()).whereIn(relation.targetFields().get(0), values);
      }
      List<String> branches = new ArrayList<>();
      List<String> seen = new ArrayList<>();
      for (Map<String, Object> parent : parents) {
        List<String> comparisons = new ArrayList<>();
        for (int idx = 0; idx < relation.localFields().size(); idx++) {
          String localField = relation.localFields().get(idx);
          if (!parent.containsKey(localField)) {
            throw new IllegalArgumentException(
                "udb: relation " + name + " missing parent field " + localField);
          }
          StringBuilder f = new StringBuilder("{\"Comparison\":{\"field\":");
          Ir.string(f, relation.targetFields().get(idx));
          f.append(",\"op\":\"eq\",\"value\":");
          Ir.writeLogicalValue(f, parent.get(localField));
          f.append("}}");
          comparisons.add(f.toString());
        }
        String branch = Ir.andFilter(comparisons);
        if (!seen.contains(branch)) {
          seen.add(branch);
          branches.add(branch);
        }
      }
      return GeneratedUdbClient.query(relation.targetMessageType()).whereFilter(Ir.orFilter(branches));
    }



    public com.udb.entity.v1.GenericDispatchResponse find(
        Map<String, Object> key, GeneratedUdbClient client) {
      return find(key, client, DEFAULT_IR_BACKEND);
    }

    public com.udb.entity.v1.GenericDispatchResponse find(
        Map<String, Object> key, GeneratedUdbClient client, String backend) {
      Query q = query().limit(1);
      for (String field : binding.primaryKeys()) {
        if (!key.containsKey(field)) {
          throw new IllegalArgumentException("udb: missing primary key field " + field);
        }
        q.where(field, "eq", key.get(field));
      }
      return q.execute(client, backend);
    }

    public com.udb.entity.v1.GenericDispatchResponse first(
        Query q, GeneratedUdbClient client) {
      return first(q, client, DEFAULT_IR_BACKEND);
    }

    public com.udb.entity.v1.GenericDispatchResponse first(
        Query q, GeneratedUdbClient client, String backend) {
      return q.limit(1).execute(client, backend);
    }

    public com.udb.entity.v1.GenericDispatchResponse all(
        Query q, GeneratedUdbClient client) {
      return all(q, client, DEFAULT_IR_BACKEND);
    }

    public com.udb.entity.v1.GenericDispatchResponse all(
        Query q, GeneratedUdbClient client, String backend) {
      return q.execute(client, backend);
    }

    public com.udb.entity.v1.GenericDispatchResponse upsert(
        Map<String, Object> record, GeneratedUdbClient client) {
      return upsert(record, client, DEFAULT_IR_BACKEND);
    }

    public com.udb.entity.v1.GenericDispatchResponse upsert(
        Map<String, Object> record, GeneratedUdbClient client, String backend) {
      validateRecord(record);
      for (String field : binding.primaryKeys()) {
        if (!record.containsKey(field)) {
          throw new IllegalArgumentException("udb: missing primary key field " + field);
        }
      }
      List<String> updateFields = new ArrayList<>();
      for (String field : record.keySet()) {
        if (!binding.primaryKeys().contains(field)) {
          updateFields.add(field);
        }
      }
      if (updateFields.isEmpty()) {
        throw new IllegalArgumentException(
            "udb: upsert requires at least one non-primary-key field");
      }
      return writeTo(binding.messageType())
          .record(record)
          .updateOnConflict(updateFields, binding.primaryKeys())
          .execute(client, backend);
    }

    public com.udb.entity.v1.GenericDispatchResponse delete(
        Map<String, Object> key, GeneratedUdbClient client) {
      return delete(key, client, DEFAULT_IR_BACKEND);
    }

    public com.udb.entity.v1.GenericDispatchResponse delete(
        Map<String, Object> key, GeneratedUdbClient client, String backend) {
      DeleteQuery d = deleteFrom(binding.messageType());
      for (String field : binding.primaryKeys()) {
        if (!key.containsKey(field)) {
          throw new IllegalArgumentException("udb: missing primary key field " + field);
        }
        d.where(field, "eq", key.get(field));
      }
      return d.execute(client, backend);
    }

    private void validateRecord(Map<String, Object> record) {
      if (binding.fields().isEmpty()) {
        return;
      }
      for (String field : record.keySet()) {
        if (!binding.fields().contains(field)) {
          throw new IllegalArgumentException(
              "udb: field "
                  + field
                  + " is not declared on entity "
                  + binding.messageType());
        }
      }
    }
  }

